package br.com.dmp.widget
import android.app.Activity
import android.os.Bundle
import android.content.Intent
import android.net.Uri
import android.widget.*
import org.json.JSONObject
import java.security.SecureRandom
import java.security.MessageDigest
class ConfigureActivity:Activity(){
 private lateinit var store:SecureStore;private lateinit var url:EditText;private lateinit var status:TextView;private lateinit var connect:Button;private lateinit var finish:Button
 override fun onCreate(b:Bundle?){super.onCreate(b);store=SecureStore(this);val panel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(28,40,28,28)};panel.addView(TextView(this).apply{text="DMP — Hoje";textSize=24f});panel.addView(TextView(this).apply{text="Informe o endereço HTTPS do seu DMP. A autorização é feita no navegador, sem PIN financeiro."});url=EditText(this).apply{hint="https://seu-dmp.onrender.com";inputType=android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_URI;textSize=16f;setText(store.connection()?.optString("base")?:"")};panel.addView(url);status=TextView(this);panel.addView(status);connect=Button(this).apply{text="Conectar DMP";setOnClickListener{pair()}};panel.addView(connect);finish=Button(this).apply{text="Concluir conexão";setOnClickListener{claim()}};panel.addView(finish);panel.addView(Button(this).apply{text="Abrir DMP / gerenciar dispositivos";setOnClickListener{try{val base=store.connection()?.optString("base")?:WidgetRules.origin(url.text.toString());startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(base+"/widget-android")))}catch(_:Exception){status.text="Informe um endereço HTTPS válido."}}});val scroll=ScrollView(this).apply{addView(panel);setOnApplyWindowInsetsListener{v,i->val space=(20*resources.displayMetrics.density).toInt();v.setPadding(0,i.systemWindowInsetTop,0,i.systemWindowInsetBottom+space);i}};setContentView(scroll);status.text=if(store.connection()!=null)"Conectado. Adicione DMP — Hoje e DMP Agenda em Widgets na tela inicial." else "Conecte e autorize no navegador. Depois volte e conclua a conexão."}
 private fun work(fn:()->String){connect.isEnabled=false;finish.isEnabled=false;Thread{val message=try{fn()}catch(_:Exception){"Não foi possível conectar. Confira o endereço e a rede; se necessário, conecte novamente."};runOnUiThread{status.text=message;connect.isEnabled=true;finish.isEnabled=true}}.start()}
 private fun pair(){val base=try{WidgetRules.origin(url.text.toString())}catch(_:Exception){status.text="Use o endereço HTTPS oficial do seu DMP.";return};work{val verifier=ByteArray(32).also{SecureRandom().nextBytes(it)}.joinToString(""){"%02x".format(it)};val challenge=MessageDigest.getInstance("SHA-256").digest(verifier.toByteArray()).joinToString(""){"%02x".format(it)};val result=WidgetApi.call(base,"/api/widget/pair",JSONObject().put("action","create").put("challenge",challenge).put("name",android.os.Build.MANUFACTURER+" "+android.os.Build.MODEL));val approval=result.getString("approvalUrl");require(WidgetRules.origin(approval)==base);store.put("pending",JSONObject().put("base",base).put("id",result.getString("id")).put("verifier",verifier).toString());runOnUiThread{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(approval)))};"Autorize no navegador, volte aqui e toque em Concluir conexão."}}
 private fun claim(){work{val p=JSONObject(store.get("pending")?:throw IllegalStateException());val base=p.getString("base");val result=WidgetApi.call(base,"/api/widget/pair",JSONObject().put("action","claim").put("id",p.getString("id")).put("verifier",p.getString("verifier")));if(result.getInt("status")==202)"Ainda não autorizado. Autorize no navegador e conclua novamente." else {val token=result.getString("token");require(Regex("dmpw_[a-f0-9]{64}").matches(token));val home=result.getString("homeUrl");require(WidgetRules.origin(home)==base);store.put("connection",JSONObject().put("base",base).put("token",token).put("home",home).toString());store.remove("snapshot");store.remove("offline");store.remove("pending");TodayWidget.schedule(this);"Conectado. Mantenha pressionada a tela inicial → Widgets → DMP — Hoje ou DMP Agenda."}}}
}
